mapper.select:
SELECT CAST(id AS CHAR) AS id,name,phone_number AS phoneNumber,company_name AS companyName,owner_work_no
AS owner,version FROM fcc_customer WHERE 1=1
AND owner_work_no=#{owner}
AND phone_number=#{phone}
ORDER BY id DESC LIMIT 50 OFFSET #{offset}

SELECT CAST(j.id AS CHAR) AS id, j.flow_key AS flowKey, j.task_type AS taskType, j.trigger_source AS triggerSource, j.biz_id AS bizId, j.created_by AS createdBy, j.status, j.max_attempts AS maxAttempts, JSON_UNQUOTE(JSON_EXTRACT(j.payload, '$.number')) AS number, JSON_UNQUOTE(JSON_EXTRACT(j.payload, '$.text')) AS text, ( SELECT COALESCE(cs.talk_duration_ms, IF(cs.answered_at IS NOT NULL AND cs.ended_at IS NOT NULL, TIMESTAMPDIFF(SECOND, cs.answered_at, cs.ended_at) * 1000, NULL)) FROM fcc_dial_attempt da LEFT JOIN fcc_call_session cs ON (da.call_id = cs.id OR cs.biz_id = CAST(da.id AS CHAR)) WHERE da.dial_job_id = j.id ORDER BY da.attempt_no DESC LIMIT 1 ) AS talkDurationMs, j.scheduled_at AS scheduledAt, j.updated_at AS updatedAt, j.created_at AS createdAt FROM fcc_dial_job j WHERE j.job_type = 'AUTO_FLOW'
AND JSON_UNQUOTE(JSON_EXTRACT(j.payload, '$.number')) LIKE CONCAT('%', #{number}, '%')
AND j.trigger_source = #{triggerSource}
AND j.status = #{status}
AND j.updated_at >= #{startTime}
AND j.updated_at <= #{endTime}
ORDER BY j.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM fcc_dial_job
WHERE job_type = 'AUTO_FLOW'

  AND JSON_UNQUOTE(JSON_EXTRACT(payload, '$.number')) LIKE CONCAT('%', #{number}, '%')


  AND trigger_source = #{triggerSource}


  AND status = #{status}


  AND updated_at >= #{startTime}


  AND updated_at <= #{endTime}
